import {buildPromotion,populateOperational,readAll} from './promotion-core.mjs';
import {displayField,sourceField} from './migration-core.mjs';

export function createReconciliation({request,connected,render,pageHead,escape:esc,reloadWorkspace,openSource,modal}){
  const model={plan:null,loading:false,busy:false,error:'',progress:'',result:null,query:'',filter:'held',year:String(new Date().getFullYear())};
  const euro=c=>c===null?'Missing':new Intl.NumberFormat('en-IE',{style:'currency',currency:'EUR',minimumFractionDigits:2}).format(c/100);
  async function load(){
    if(model.busy)return;if(!connected()){model.error='Connect Supabase in Settings to reconcile source records.';render();return;}
    model.loading=true;model.error='';render();
    try{const [rows,services]=await Promise.all([readAll(request,'migration_staging'),readAll(request,'services')]);model.plan=await buildPromotion(rows,{existingServices:services});}
    catch(e){model.error=`Reconciliation could not load: ${e.message}`;}
    finally{model.loading=false;render();}
  }
  async function populate(){
    if(!model.plan||model.busy)return;model.busy=true;model.error='';model.progress='Checking existing operational records…';render();
    try{model.result=await populateOperational(model.plan,request,message=>{model.progress=message;render();});await reloadWorkspace();model.progress='Working tables populated and verified. Existing records and review statuses were preserved.';}
    catch(e){model.error=`Population stopped: ${e.message}. Completed records are preserved; retry to resume.`;}
    finally{model.busy=false;render();}
  }
  function view(){
    const p=model.plan;
    const head=pageHead('Reconciliation','Review source coverage, populate working records, and resolve financial differences.',`<button class="btn" data-reconcile-refresh ${model.loading||model.busy?'disabled':''}>Refresh</button><button class="btn primary" data-reconcile-populate ${!p||model.busy||model.loading?'disabled':''}>Populate working tables</button>`);
    const alerts=`${model.loading?'<div class="source-progress" role="status">Reading source records and checking relationships…</div>':''}${model.progress?`<div class="source-progress" role="status">${esc(model.progress)}</div>`:''}${model.error?`<div class="source-error" role="alert">${esc(model.error)}</div>`:''}`;
    if(!p)return head+alerts;
    const projects=p.projectReview.filter(r=>(model.filter!=='held'||r.reasons.length)&&(model.filter!=='financial'||r.financialReasons.length)&&(!model.query||r.row.raw_record.name.toLowerCase().includes(model.query.toLowerCase()))).sort((a,b)=>a.row.raw_record.name.localeCompare(b.row.raw_record.name));
    const issue=(label,n)=>`<span class="pill">${esc(label)}: ${n}</span>`;
    const cards=[['Accounts',p.summary.accounts,'Client and vendor records'],['Projects ready',p.summary.projects,`${p.summary.heldProjects} need required fields`],['Revenue schedule months',p.summary.scheduleMonths,'Linked sums match source contract'],['Vendor budgets ready',p.summary.plannedCosts,'Explicit budgets only; actuals pending']];
    const years=[...new Set(p.monthly.map(m=>m.month.slice(0,4)))];
    return head+alerts+`<div class="notice source-notice"><span><b>${p.sourceCount.toLocaleString()} source records</b> · Operational records remain Needs review. Invoice and payment actuals require SuperFaktura reconciliation. Missing values are held for review.</span></div>
    <div class="stats">${cards.map(([label,n,sub])=>`<div class="stat"><div class="stat-top">${label}</div><div class="stat-value">${n}</div><div class="stat-foot">${sub}</div></div>`).join('')}</div>
    ${model.result?`<div class="notice"><span>Verified working tables · ${Object.entries(model.result.created).map(([table,n])=>`${n} new ${table.replaceAll('_',' ')}`).join(' · ')}. Repeating this operation keeps existing rows.</span></div>`:''}
    <div class="card"><div class="card-head"><div><div class="card-title">Monthly source reconciliation</div><div class="card-sub">Company target and ClickUp revenue rows · EUR. These are source figures, not accounting actuals.</div></div><select aria-label="Reconciliation year" data-reconcile-year>${years.map(y=>`<option ${model.year===y?'selected':''}>${y}</option>`).join('')}</select></div><div class="table-wrap"><table class="table"><thead><tr><th>Month</th><th>Company target</th><th>Source revenue</th><th>Source − target</th><th>ClickUp paid · unverified</th><th>Revenue rows</th></tr></thead><tbody>${p.monthly.filter(m=>m.month.startsWith(model.year)).map(m=>`<tr><td>${m.month}</td><td>${m.target===null?'Not set':euro(m.target)}</td><td>${euro(m.sourceRevenue)}</td><td>${m.target===null?'—':euro(m.sourceRevenue-m.target)}</td><td>${euro(m.paidSource)}</td><td>${m.rows}</td></tr>`).join('')}</tbody></table></div><div class="card-body card-sub">R PLAN months use record names as approved. Taktika EXT maps to Taktika; original source values remain available. Source revenue includes draft, invoiced, paid and complaint records; this table does not recognize revenue or infer cash collection.</div></div>
    <div class="card" style="margin-top:16px"><div class="card-head"><div><div class="card-title">Data gaps</div><div class="card-sub">Gaps can overlap. Budget and final-invoice fields remain separate.</div></div></div><div class="card-body"><div class="filters">${issue('Revenue without project',p.revenueIssues.missingProject.length)}${issue('Source revenue missing direct client',p.revenueIssues.missingClient.length)}${issue('Client links recovered by exact IDs',p.recoveries.length)}${issue('Revenue amount missing',p.revenueIssues.missingAmount.length)}${issue('Negative revenue to review',p.revenueIssues.negativeAmount.length)}${issue('Costs without project',p.costIssues.missingProject.length)}${issue('Costs without vendor',p.costIssues.missingVendor.length)}${issue('Costs without budget',p.costIssues.missingBudget.length)}${issue('Final invoice before receipt',p.costIssues.prematureFinalInvoice.length)}${issue('Overhead held separately',p.costIssues.overhead.length)}${issue('Contacts needing affiliations',p.contactReview.filter(c=>c.reasons.length).length)}</div></div></div>
    <div class="card" style="margin-top:16px"><div class="card-head"><div><div class="card-title">Project review queue</div><div class="card-sub">Actual Project records only; subtasks and milestones stay in Source records.</div></div><span class="pill">${projects.length} matching</span></div><div class="toolbar"><form data-reconcile-search class="search"><input name="query" aria-label="Search reconciliation projects" placeholder="Search projects" value="${esc(model.query)}"><button class="btn small">Search</button></form><select aria-label="Project reconciliation filter" data-reconcile-filter><option value="held" ${model.filter==='held'?'selected':''}>Missing required fields</option><option value="financial" ${model.filter==='financial'?'selected':''}>Revenue differences</option><option value="all" ${model.filter==='all'?'selected':''}>All projects</option></select></div><div class="table-wrap"><table class="table"><thead><tr><th>Project / client</th><th>Group</th><th>Contract · source</th><th>Linked revenue</th><th>Difference</th><th>Review</th></tr></thead><tbody>${projects.slice(0,100).map(r=>`<tr><td><button class="link source-record-link" data-reconcile-source="${esc(r.row.id)}">${esc(r.row.raw_record.name)}</button><span class="secondary">${esc(displayField(sourceField(r.row.raw_record,'CLIENT'))||(r.clientIds.length===1?(p.tables.accounts.find(a=>a.source_external_id.endsWith(`:${r.clientIds[0]}`))?.name||'Client missing'):'Client missing'))}${r.clientOrigin==='Consistent linked revenue IDs'?' · via linked revenue':''}</span></td><td>${esc(r.group||'Missing')}</td><td>${euro(r.contract)}</td><td>${euro(r.revenueTotal)}<span class="secondary">${r.revenueRows} source rows</span></td><td>${r.contract===null?'—':euro(r.revenueTotal-r.contract)}</td><td>${esc([...r.reasons,...r.financialReasons].join(' · ')||'Ready for source schedule')}${r.reasons.length?`<button class="btn small" style="display:block;margin-top:8px" data-reconcile-resolve="${esc(r.row.id)}">Resolve mapping</button>`:''}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">No projects match this view.</td></tr>'}</tbody></table></div><div class="source-pagination">Showing ${Math.min(100,projects.length)} of ${projects.length}; search to narrow the queue.</div></div>`;
  }
  function bind(root){
    root.querySelector('[data-reconcile-refresh]')?.addEventListener('click',load);
    root.querySelector('[data-reconcile-populate]')?.addEventListener('click',populate);
    root.querySelector('[data-reconcile-year]')?.addEventListener('change',e=>{model.year=e.target.value;render();});
    root.querySelector('[data-reconcile-filter]')?.addEventListener('change',e=>{model.filter=e.target.value;render();});
    root.querySelector('[data-reconcile-search]')?.addEventListener('submit',e=>{e.preventDefault();model.query=new FormData(e.currentTarget).get('query');render();});
    root.querySelectorAll('[data-reconcile-source]').forEach(el=>el.addEventListener('click',()=>{const r=model.plan.projectReview.find(r=>r.row.id===el.dataset.reconcileSource);if(r)openSource(r.row);}));
    root.querySelectorAll('[data-reconcile-resolve]').forEach(el=>el.addEventListener('click',()=>resolve(el.dataset.reconcileResolve)));
  }
  function resolve(id){
    const review=model.plan?.projectReview.find(r=>r.row.id===id);if(!review||model.busy)return;
    const clients=model.plan.tables.accounts.filter(a=>a.kind==='Client').sort((a,b)=>a.name.localeCompare(b.name));
    const selected=review.clientIds.length===1?model.plan.tables.accounts.find(a=>a.source_external_id.endsWith(`:${review.clientIds[0]}`)):null;
    const phase=review.row.raw_record._bizbase_mapping?.phase||displayField(sourceField(review.row.raw_record,'PROJECT PHASE'));
    const dialog=modal('Resolve project mapping',review.row.raw_record.name,`<p class="card-sub">${esc(review.reasons.join(' · '))}. This saves your intended mapping alongside the unchanged ClickUp source.</p><form id="resolve-project-form" class="form-grid"><div class="field full"><label>Client</label><select name="client" required><option value="">Choose a client</option>${clients.map(a=>`<option value="${esc(a.source_external_id.split(':').at(-1))}" ${a.id===selected?.id?'selected':''}>${esc(a.name)}</option>`).join('')}</select></div><div class="field"><label>Group</label><select name="group" required><option value="">Choose a group</option>${['Strategia','Transformacia','Taktika'].map(g=>`<option ${review.group===g?'selected':''}>${g}</option>`).join('')}</select></div><div class="field"><label>Contract value · EUR</label><input name="amount" aria-label="Resolved contract value in EUR" type="number" min="0" step="0.01" required value="${review.contract===null?'':review.contract/100}"></div><div class="field full"><label>Project phase</label><select name="phase" required><option value="">Choose a phase</option><option value="03 IN PROGRESS" ${phase==='03 IN PROGRESS'?'selected':''}>In delivery</option><option value="08 CLOSED" ${phase==='08 CLOSED'?'selected':''}>Completed</option></select></div><div class="field full"><label>Reason for the correction</label><input name="reason" required placeholder="e.g. Confirmed from signed proposal"></div></form><div data-mapping-error class="source-error" role="alert" hidden></div>`,`<button class="btn" data-close>Cancel</button><button class="btn primary" type="submit" form="resolve-project-form">Save mapping</button>`);
    dialog.querySelector('form').addEventListener('submit',async e=>{
      e.preventDefault();const submit=dialog.querySelector('[type=submit]'),error=dialog.querySelector('[data-mapping-error]');submit.disabled=true;error.hidden=true;
      try{
        const f=Object.fromEntries(new FormData(e.currentTarget));
        if(!clients.some(a=>a.source_external_id.endsWith(`:${f.client}`))||!['Strategia','Transformacia','Taktika'].includes(f.group)||!/^\d+(?:\.\d{1,2})?$/.test(f.amount)||!['03 IN PROGRESS','08 CLOSED'].includes(f.phase)||!f.reason.trim())throw Error('Complete every mapping field with a valid value.');
        const latest=await request(`migration_staging?select=raw_record,validation_notes&id=eq.${id}`);if(latest.length!==1)throw Error('Source record no longer available.');
        const raw=latest[0].raw_record,mapping={client_source_id:f.client,group:f.group,contract_value:f.amount,phase:f.phase,reason:f.reason.trim(),confirmed_at:new Date().toISOString()};
        const history=[...(raw._bizbase_mapping_history||[]),...(raw._bizbase_mapping?[raw._bizbase_mapping]:[])];
        await request(`migration_staging?id=eq.${id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({raw_record:{...raw,_bizbase_mapping:mapping,_bizbase_mapping_history:history},validation_notes:`${latest[0].validation_notes||''}\nProject mapping confirmed: ${f.reason.trim()}. Financial validation remains pending.`})});
        dialog.remove();model.progress='Project mapping saved. Refresh the promotion plan, then Populate working tables to add newly ready records.';await load();
      }catch(e){error.textContent=e.message;error.hidden=false;submit.disabled=false;}
    });
  }
  return {view,bind,load,populate};
}
